/* ================= 3D DEPTH-OF-FIELD GT6 PARTICLE CANVAS ================= */
function GT6Particles({ mode = 'drift', theme = 'dark' }) {
  const canvasRef = useRef(null);
  const mouseRef = useRef({ x: 0, y: 0 });

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    let animationFrameId;

    let width = (canvas.width = canvas.offsetWidth);
    let height = (canvas.height = canvas.offsetHeight);

    const handleResize = () => {
      if (!canvas) return;
      width = canvas.width = canvas.offsetWidth;
      height = canvas.height = canvas.offsetHeight;
    };
    window.addEventListener('resize', handleResize);

    const handleMouseMove = (e) => {
      const rect = canvas.getBoundingClientRect();
      mouseRef.current = {
        x: (e.clientX - rect.left - width / 2) * 0.0005,
        y: (e.clientY - rect.top - height / 2) * 0.0005,
      };
    };
    window.addEventListener('mousemove', handleMouseMove);

    const count = mode === 'heavy' ? 90 : mode === 'grid' ? 60 : 45;
    const particles = [];
    const particleColor = theme === 'light' ? '212, 175, 55' : '6, 182, 212';

    for (let i = 0; i < count; i++) {
      particles.push({
        x: (Math.random() - 0.5) * width * 1.8,
        y: (Math.random() - 0.5) * height * 1.8,
        z: Math.random() * 850 + 40,
        vx: (Math.random() - 0.5) * 0.5,
        vy: mode === 'up' ? -Math.random() * 1.4 - 0.4 : (Math.random() - 0.5) * 0.4,
        vz: (Math.random() - 0.5) * 1.8,
        baseRadius: Math.random() * 3.5 + 1,
        alpha: Math.random() * 0.8 + 0.15,
      });
    }

    const focalLength = 450;
    const render = () => {
      ctx.clearRect(0, 0, width, height);

      if (mode === 'grid') {
        ctx.strokeStyle = `rgba(${particleColor}, 0.045)`;
        ctx.lineWidth = 1;
        const gridSize = 80;
        for (let x = 0; x < width; x += gridSize) {
          ctx.beginPath();
          ctx.moveTo(x, 0);
          ctx.lineTo(x, height);
          ctx.stroke();
        }
        for (let y = 0; y < height; y += gridSize) {
          ctx.beginPath();
          ctx.moveTo(0, y);
          ctx.lineTo(width, y);
          ctx.stroke();
        }
      }

      particles.sort((a, b) => b.z - a.z);

      particles.forEach((p) => {
        p.x += p.vx + mouseRef.current.x * 15;
        p.y += p.vy + mouseRef.current.y * 15;
        p.z += p.vz;

        if (p.z < 10) p.z = 850;
        if (p.z > 900) p.z = 20;

        const centerX = width / 2;
        const centerY = height / 2;

        const scale = focalLength / p.z;
        const screenX = centerX + p.x * scale;
        const screenY = centerY + p.y * scale;

        if (screenX < -50 || screenX > width + 50 || screenY < -50 || screenY > height + 50) return;

        const radius = Math.max(0.6, p.baseRadius * scale);
        const focusPlane = 450;
        const distanceToFocus = Math.abs(p.z - focusPlane);
        const blurAmount = Math.min(20, (distanceToFocus / 300) * 7);

        ctx.save();
        ctx.filter = blurAmount > 0.8 ? `blur(${blurAmount.toFixed(1)}px)` : 'none';
        const depthAlpha = Math.min(1, Math.max(0.1, p.alpha * (scale * 0.95)));

        ctx.beginPath();
        ctx.arc(screenX, screenY, radius, 0, Math.PI * 2);
        ctx.fillStyle = `rgba(${particleColor}, ${depthAlpha})`;
        ctx.fill();

        ctx.restore();
      });

      animationFrameId = requestAnimationFrame(render);
    };

    render();

    return () => {
      window.removeEventListener('resize', handleResize);
      window.removeEventListener('mousemove', handleMouseMove);
      cancelAnimationFrame(animationFrameId);
    };
  }, [mode, theme]);

  return (
    <>
      <canvas ref={canvasRef} className="absolute inset-0 w-full h-full pointer-events-none z-0" />
      <div className="absolute inset-0 pointer-events-none z-0 opacity-15 bg-[linear-gradient(rgba(18,16,16,0)_50%,rgba(0,0,0,0.4)_50%)] bg-[length:100%_4px]" />
    </>
  );
}

