function AnimatedRoutes({ children }) {
  const location = useLocation();
  return (
    <AnimatePresence mode="wait">
      <Routes location={location} key={location.pathname}>
        {children}
      </Routes>
    </AnimatePresence>
  );
}

/* ================= 3D DEPTH-OF-FIELD GT6 PARTICLE CANVAS ================= */
function GT6Particles({ mode = 'drift', theme = 'dark' }) {
  const canvasRef = useRef(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    let animationFrameId;

    let width = (canvas.width = canvas.offsetWidth);
    let height = (canvas.height = canvas.offsetHeight);

    const handleResize = () => {
      if (!canvas) return;
      width = canvas.width = canvas.offsetWidth;
      height = canvas.height = canvas.offsetHeight;
    };
    window.addEventListener('resize', handleResize);

    const count = mode === 'heavy' ? 80 : mode === 'grid' ? 50 : 40;
    const particles = [];
    const particleColor = theme === 'light' ? '212, 175, 55' : '6, 182, 212'; // Gold for light mode, Cyan for dark/grey

    // Initialize 3D particles (x, y, z)
    for (let i = 0; i < count; i++) {
      particles.push({
        x: (Math.random() - 0.5) * width * 1.5,
        y: (Math.random() - 0.5) * height * 1.5,
        z: Math.random() * 800 + 50, // Depth from 50 (very close) to 850 (far away)
        vx: (Math.random() - 0.5) * 0.6,
        vy: mode === 'up' ? -Math.random() * 1.2 - 0.3 : (Math.random() - 0.5) * 0.5,
        vz: (Math.random() - 0.5) * 1.5, // Moving forward or backward in 3D space
        baseRadius: Math.random() * 3 + 1,
        alpha: Math.random() * 0.7 + 0.2,
      });
    }

    const focalLength = 400; // Camera focal length for 3D perspective projection

    let tick = 0;
    const render = () => {
      tick++;
      ctx.clearRect(0, 0, width, height);

      // Render subtle GT6 perspective grid lines if mode is 'grid'
      if (mode === 'grid') {
        ctx.strokeStyle = `rgba(${particleColor}, 0.035)`;
        ctx.lineWidth = 1;
        const gridSize = 70;
        const centerX = width / 2;
        const centerY = height / 2;
        for (let x = 0; x < width; x += gridSize) {
          ctx.beginPath();
          ctx.moveTo(x, 0);
          ctx.lineTo(x, height);
          ctx.stroke();
        }
        for (let y = 0; y < height; y += gridSize) {
          ctx.beginPath();
          ctx.moveTo(0, y);
          ctx.lineTo(width, y);
          ctx.stroke();
        }
      }

      // Sort particles by Z depth (painter's algorithm: draw far particles first)
      particles.sort((a, b) => b.z - a.z);

      particles.forEach((p) => {
        // Update 3D position
        p.x += p.vx;
        p.y += p.vy;
        p.z += p.vz;

        // Wrap around 3D boundaries
        if (p.z < 10) p.z = 850;
        if (p.z > 900) p.z = 20;
        
        const centerX = width / 2;
        const centerY = height / 2;

        if (p.x + centerX < -200 || p.x + centerX > width + 200) p.vx *= -1;
        if (p.y + centerY < -200 || p.y + centerY > height + 200) p.vy *= -1;

        // Perspective projection formula
        const scale = focalLength / p.z;
        const screenX = centerX + p.x * scale;
        const screenY = centerY + p.y * scale;

        // Skip if offscreen
        if (screenX < -50 || screenX > width + 50 || screenY < -50 || screenY > height + 50) return;

        const radius = Math.max(0.5, p.baseRadius * scale);

        // Depth-of-Field (DoF) Blur Calculation:
        // Particles very close (low Z, e.g. < 200) or very far have blur. Mid-depth is sharp.
        const focusPlane = 450;
        const distanceToFocus = Math.abs(p.z - focusPlane);
        const blurAmount = Math.min(18, (distanceToFocus / 300) * 6); // Close objects get heavy blur like GT6 bokeh!

        ctx.save();
        ctx.filter = blurAmount > 0.8 ? `blur(${blurAmount.toFixed(1)}px)` : 'none';

        // Opacity mapping based on depth
        const depthAlpha = Math.min(1, Math.max(0.08, p.alpha * (scale * 0.9)));

        ctx.beginPath();
        ctx.arc(screenX, screenY, radius, 0, Math.PI * 2);
        ctx.fillStyle = `rgba(${particleColor}, ${depthAlpha})`;
        ctx.fill();

        // Extra bokeh bloom glow for foreground/midground particles
        if (radius > 2.5 && blurAmount > 1) {
          ctx.beginPath();
          ctx.arc(screenX, screenY, radius * 2.2, 0, Math.PI * 2);
          ctx.fillStyle = `rgba(${particleColor}, ${depthAlpha * 0.25})`;
          ctx.fill();
        }

        ctx.restore();
      });

      animationFrameId = requestAnimationFrame(render);
    };

    render();

    return () => {
      window.removeEventListener('resize', handleResize);
      cancelAnimationFrame(animationFrameId);
    };
  }, [mode, theme]);

  return <canvas ref={canvasRef} className="absolute inset-0 w-full h-full pointer-events-none z-0" />;
}

