/* ================= CINEMATIC EDITORIAL IMAGE TEXT SECTION ================= */
function ImageTextSection({ image, heading, text, reverse = false, theme, particleMode = 'drift' }) {
  const sectionBg = {
    dark: 'bg-[#080808] text-white border-white/10',
    grey: 'bg-[#161b22] text-gray-100 border-white/10',
    light: 'bg-[#191715] text-gray-200 border-amber-900/30',
  }[theme];

  return (
    <section className={`relative w-full overflow-hidden py-28 border-t ${sectionBg}`}>
      <GT6Particles mode={particleMode} theme={theme} />
      <div className="max-w-7xl mx-auto flex flex-col lg:flex-row items-center px-6 lg:px-12 gap-16 relative z-10">
        <div
          className={`flex-1 w-full h-[420px] relative overflow-hidden rounded-md border shadow-2xl group ${
            theme === 'light' ? 'border-amber-500/30' : 'border-white/10'
          } ${reverse ? 'lg:order-2' : ''}`}
        >
          <img src={image} alt={heading} className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-700 filter brightness-90" />
          <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-black/20 to-transparent" />
        </div>

        <div className="flex-1 text-left">
          <motion.div
            initial={{ opacity: 0, x: reverse ? 30 : -30 }}
            whileInView={{ opacity: 1, x: 0 }}
            transition={{ duration: 0.6 }}
          >
            <span className={`text-xs uppercase tracking-[0.3em] font-bold block mb-3 font-sans ${theme === 'light' ? 'text-amber-400' : 'text-cyan-400'}`}>Studio Archive</span>
            <h2 className="text-3xl md:text-5xl font-extrabold mb-6 tracking-tight font-sans">
              {heading}
            </h2>
          </motion.div>

          <motion.p
            initial={{ opacity: 0 }}
            whileInView={{ opacity: 1 }}
            transition={{ delay: 0.2, duration: 0.6 }}
            className={`text-base md:text-lg leading-relaxed font-sans border-l-2 pl-6 py-2 ${
              theme === 'light' ? 'border-amber-400 text-gray-300' : 'border-cyan-400 text-gray-300'
            }`}
          >
            {text}
          </motion.p>
        </div>
      </div>
    </section>
  );
}

