import React, { useState, useEffect, useRef } from "react";
import { motion, AnimatePresence } from "framer-motion";

export default function LabCompanion({ theme = 'dark' }) {
  const [isOpen, setIsOpen] = useState(false);
  const [mood, setMood] = useState('idle'); // 'idle', 'talking', 'thinking', 'excited'
  const [inputMessage, setInputMessage] = useState("");
  const [messages, setMessages] = useState([
    { sender: 'bot', text: "SYSTEM ONLINE. I'm your lab assistant! Ask me anything about the experiments or click a prompt below." }
  ]);
  const messagesEndRef = useRef(null);

  // Theme styling mapping
  const companionStyles = {
    dark: {
      bg: 'bg-black/95 border-cyan-500/50',
      text: 'text-cyan-400',
      bubble: 'bg-cyan-950/60 border-cyan-500/30 text-gray-200',
      userBubble: 'bg-cyan-500 text-black',
      inputBg: 'bg-black border-cyan-500/40 text-cyan-300 focus:border-cyan-400',
      btnBg: 'bg-cyan-500 text-black hover:bg-cyan-400',
      avatarBorder: 'border-cyan-400 shadow-[0_0_15px_rgba(34,211,238,0.4)]',
    },
    grey: {
      bg: 'bg-[#161b22]/95 border-cyan-600/50',
      text: 'text-cyan-400',
      bubble: 'bg-cyan-950/40 border-cyan-600/30 text-gray-200',
      userBubble: 'bg-cyan-600 text-white',
      inputBg: 'bg-[#0d1117] border-cyan-600/40 text-cyan-300 focus:border-cyan-400',
      btnBg: 'bg-cyan-600 text-white hover:bg-cyan-500',
      avatarBorder: 'border-cyan-500 shadow-[0_0_15px_rgba(34,211,238,0.3)]',
    },
    light: {
      bg: 'bg-[#1b1916]/95 border-amber-500/50',
      text: 'text-amber-400',
      bubble: 'bg-amber-950/40 border-amber-900/40 text-gray-200',
      userBubble: 'bg-amber-500 text-black',
      inputBg: 'bg-[#141210] border-amber-500/40 text-amber-300 focus:border-amber-400',
      btnBg: 'bg-amber-500 text-black hover:bg-amber-400',
      avatarBorder: 'border-amber-400 shadow-[0_0_15px_rgba(212,175,55,0.4)]',
    },
  }[theme];

  // Predefined Knowledge Base & Quick Questions
  const knowledgeBase = [
    {
      keywords: ['unity', 'game', 'prototype', 'experiment 1'],
      response: "Experiment 01 features an interactive WebGL Unity prototype. You can interact directly with the scene or hit 'RELOAD_PROTOTYPE' below it!"
    },
    {
      keywords: ['3d', 'model', 'object', 'experiment 2'],
      response: "Experiment 02 showcases real-time 3D object rendering with custom inspection controls in the lab view."
    },
    {
      keywords: ['ai', 'remaster', 'texture', 'kota', 'vader', 'starkiller', 'experiment 3'],
      response: "Experiment 03 highlights AI texture upscaling, normal map generation, and style transfer across classic retro asset pipelines!"
    },
    {
      keywords: ['roberto', 'creator', 'developer', 'who'],
      response: "This entire research division and platform was built by Roberto Bliaja, specializing in core game systems design, custom AI, and graphics programming."
    },
    {
      keywords: ['hello', 'hi', 'hey', 'greetings'],
      response: "Greetings, operator! How can I assist your research in the lab today?"
    }
  ];

  const quickPrompts = [
    "Tell me about the Unity prototype",
    "What is Experiment 03?",
    "Who built this lab?",
    "System status?"
  ];

  const handleSend = (textToSend) => {
    const query = textToSend || inputMessage;
    if (!query.trim()) return;

    const userMsg = { sender: 'user', text: query };
    setMessages(prev => [...prev, userMsg]);
    if (!textToSend) setInputMessage("");
    setMood('thinking');

    setTimeout(() => {
      setMood('talking');
      const lowerQuery = query.toLowerCase();
      let matchedReply = "Query not recognized in local logs. Try asking about the Unity prototype, 3D models, AI remasters, or the creator!";

      for (let item of knowledgeBase) {
        if (item.keywords.some(kw => lowerQuery.includes(kw))) {
          matchedReply = item.response;
          break;
        }
      }

      setMessages(prev => [...prev, { sender: 'bot', text: matchedReply }]);
      setTimeout(() => setMood('idle'), 2000);
    }, 600);
  };

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, isOpen]);

  return (
    <div className="fixed bottom-6 right-6 z-50 font-mono">
      {/* Chat Window Popup */}
      <AnimatePresence>
        {isOpen && (
          <motion.div
            initial={{ opacity: 0, y: 20, scale: 0.95 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, y: 20, scale: 0.95 }}
            className={`mb-4 w-80 md:w-96 rounded-lg border-2 ${companionStyles.bg} p-4 shadow-2xl backdrop-blur-md flex flex-col h-[450px]`}
          >
            {/* Header */}
            <div className="flex items-center justify-between border-b pb-3 border-white/10 mb-3">
              <div className="flex items-center gap-2">
                <div className={`w-3 h-3 rounded-full animate-pulse ${mood === 'talking' ? 'bg-green-400' : mood === 'thinking' ? 'bg-yellow-400' : 'bg-cyan-400'}`} />
                <span className={`text-xs font-black tracking-widest ${companionStyles.text}`}>AI_COMPANION // v1.0</span>
              </div>
              <button 
                onClick={() => setIsOpen(false)}
                className="text-gray-400 hover:text-white text-xs font-black px-2 py-0.5 border border-white/10 hover:border-white/40"
              >
                [X]
              </button>
            </div>

            {/* Messages Box */}
            <div className="flex-1 overflow-y-auto space-y-3 pr-2 scrollbar-thin text-xs">
              {messages.map((m, idx) => (
                <div key={idx} className={`flex ${m.sender === 'user' ? 'justify-end' : 'justify-start'}`}>
                  <div className={`max-w-[85%] p-3 rounded-md border ${m.sender === 'user' ? companionStyles.userBubble : companionStyles.bubble}`}>
                    {m.text}
                  </div>
                </div>
              ))}
              <div ref={messagesEndRef} />
            </div>

            {/* Quick Prompt Chips */}
            <div className="py-2 flex gap-1.5 overflow-x-auto no-scrollbar">
              {quickPrompts.map((prompt, i) => (
                <button
                  key={i}
                  onClick={() => handleSend(prompt)}
                  className="whitespace-nowrap px-2 py-1 text-[9px] border border-white/10 rounded bg-white/5 hover:bg-white/10 text-gray-300 transition-all"
                >
                  {prompt}
                </button>
              ))}
            </div>

            {/* Input Bar */}
            <div className="flex gap-2 pt-2 border-t border-white/10">
              <input
                type="text"
                placeholder="Ask companion..."
                value={inputMessage}
                onChange={(e) => setInputMessage(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && handleSend()}
                className={`flex-1 px-3 py-2 text-xs border rounded focus:outline-none ${companionStyles.inputBg}`}
              />
              <button
                onClick={() => handleSend()}
                className={`px-4 py-2 text-xs font-black rounded transition-all ${companionStyles.btnBg}`}
              >
                SEND
              </button>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Floating Character Avatar Button */}
      <motion.button
        onClick={() => setIsOpen(!isOpen)}
        whileHover={{ scale: 1.05 }}
        whileTap={{ scale: 0.95 }}
        className={`relative flex items-center justify-center w-16 h-16 rounded-full border-2 ${companionStyles.avatarBorder} bg-black overflow-hidden group shadow-2xl`}
      >
        {/* Animated Avatar State Display */}
        <div className="absolute inset-0 flex items-center justify-center bg-gradient-to-b from-black via-gray-900 to-black">
          {mood === 'thinking' ? (
            <div className="flex gap-1 animate-bounce">
              <span className="w-1.5 h-1.5 bg-yellow-400 rounded-full" />
              <span className="w-1.5 h-1.5 bg-yellow-400 rounded-full" />
              <span className="w-1.5 h-1.5 bg-yellow-400 rounded-full" />
            </div>
          ) : mood === 'talking' ? (
            <div className="text-xl font-black text-green-400 animate-pulse">💬</div>
          ) : (
            <div className="flex flex-col items-center">
              <div className="w-4 h-2 border-b-2 border-cyan-400 rounded-b-full mb-1 animate-pulse" />
              <span className="text-[9px] font-black tracking-tighter text-cyan-300">AI.BOT</span>
            </div>
          )}
        </div>

        {/* Notification indicator dot */}
        <span className="absolute top-1 right-1 w-3 h-3 bg-cyan-400 border-2 border-black rounded-full animate-ping" />
      </motion.button>
    </div>
  );
}